# Test successful operation
@pytest.mark.parametrize("status", ["available", "pending", "sold", None])
def test_find_pets_by_status_success(base_url, auth_headers, status):
    """
    Test successful retrieval of pets based on status.
    """
    params = {"status": status} if status else {}
    response = requests.get(f"{base_url}/pet/findByStatus", headers=auth_headers, params=params)
    
    assert response.status_code == 200
    assert isinstance(response.json(), list)

    # Validate the response schema based on the example in the spec
    for pet in response.json():
        assert isinstance(pet['name'], str)
        assert isinstance(pet['photoUrls'], list)
        if 'id' in pet:
            assert isinstance(pet['id'], int)
        if 'category' in pet:
            assert isinstance(pet['category']['id'], int)
            assert isinstance(pet['category']['name'], str)
        if 'status' in pet:
            assert pet['status'] in ["available", "pending", "sold"]

